<script setup lang="ts">
import { computed, ref, useId } from 'vue'
const id=useId()
const items=ref([{id:'headphones',name:'Headphones',unitCents:8900,quantity:1},{id:'cable',name:'USB-C cable',unitCents:900,quantity:2},{id:'case',name:'Travel case',unitCents:1800,quantity:1}])
const code=ref('')
const applied=ref(false)
const message=ref('No promo applied.')
const receiptVisible=ref(false)
const replay=ref(0)
const subtotal=computed(()=>items.value.reduce((sum,x)=>sum+x.unitCents*x.quantity,0))
const discount=computed(()=>applied.value?Math.round(subtotal.value*.1):0)
const tax=computed(()=>Math.round((subtotal.value-discount.value)*.08))
const total=computed(()=>subtotal.value-discount.value+tax.value)
const money=(cents:number)=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(cents/100)
const receipt=computed(()=>['SAMPLE CART - NOT A PAYMENT RECEIPT',...items.value.map(x=>`${x.quantity} x ${x.name}: ${money(x.unitCents*x.quantity)}`),`Subtotal: ${money(subtotal.value)}`,`Discount: -${money(discount.value)}`,`Illustrative tax (8%): ${money(tax.value)}`,`Example total: ${money(total.value)}`].join('\n'))
function apply(){applied.value=code.value.trim().toUpperCase()==='WELCOME10';message.value=applied.value?'WELCOME10 applied: 10% off items.':'Unknown code. No discount applied.'}
function remove(){applied.value=false;code.value='';message.value='Promo removed.'}
function reset(){items.value.forEach(x=>x.quantity=x.id==='cable'?2:1);remove();message.value='No promo applied.';receiptVisible.value=false;replay.value=0}
</script>
<template>
<section class="cart-summary-demo" aria-label="Local cart summary example"><p class="cart-warning">Example only. No checkout, payment or order is created.</p><div class="cart-grid"><div><h3>Items</h3><ul><li v-for="item in items" :key="item.id"><div><strong>{{ item.name }}</strong><small>{{ money(item.unitCents) }} each</small></div><label :for="id+'-'+item.id">Quantity<select :id="id+'-'+item.id" v-model.number="item.quantity"><option v-for="n in [0,1,2,3,4,5]" :key="n" :value="n">{{ n }}</option></select></label><span>{{ money(item.unitCents*item.quantity) }}</span></li></ul><p v-if="subtotal===0" class="cart-empty">Your example cart is empty. Choose a quantity to restore items.</p></div><div><h3>Summary</h3><form @submit.prevent="apply"><label :for="id+'-promo'">Promo code (try WELCOME10)</label><div class="promo-row"><input :id="id+'-promo'" v-model="code" maxlength="30" autocomplete="off"><button type="submit" :disabled="subtotal===0">Apply</button></div></form><p role="status">{{ message }}</p><button v-if="applied" type="button" @click="remove">Remove promo</button><dl><div><dt>Subtotal</dt><dd data-value="subtotal">{{ money(subtotal) }}</dd></div><div><dt>Discount{{ applied?' (WELCOME10)':'' }}</dt><dd data-value="discount">-{{ money(discount) }}</dd></div><div><dt>Illustrative tax (8%)</dt><dd data-value="tax">{{ money(tax) }}</dd></div><div class="cart-total"><dt>Example total</dt><dd data-value="total">{{ money(total) }}</dd></div></dl><button type="button" :disabled="subtotal===0&&!receiptVisible" :aria-expanded="receiptVisible" :aria-controls="id+'-receipt'" @click="receiptVisible=!receiptVisible">{{ receiptVisible?'Hide summary text':'Preview summary text' }}</button></div></div><div v-if="receiptVisible" :id="id+'-receipt'" :key="replay" class="cart-preview"><h3>Live summary text</h3><p>Fictitious USD values, not proof of payment. Changes to the cart update this preview.</p><label>Read-only summary<textarea readonly rows="9" :value="receipt"></textarea></label><button type="button" @click="replay++">Replay reveal</button></div><button type="button" class="cart-reset" @click="reset">Reset example</button></section>
</template>
<style scoped>
.cart-summary-demo{border:1px solid var(--vp-c-divider);border-radius:14px;padding:18px;margin:20px 0}.cart-warning{font-weight:650;color:var(--vp-c-text-2)}.cart-grid{display:grid;grid-template-columns:1.1fr 1fr;gap:24px}.cart-grid>div{min-width:0}.cart-summary-demo h3{margin:12px 0}.cart-summary-demo ul{padding:0;list-style:none}.cart-summary-demo li{display:grid;grid-template-columns:minmax(0,1fr) 84px;gap:8px;border-bottom:1px solid var(--vp-c-divider);padding:14px 0}.cart-summary-demo li>span{text-align:right;grid-column:2}.cart-summary-demo strong,.cart-summary-demo small{display:block;overflow-wrap:anywhere}.cart-summary-demo small{color:var(--vp-c-text-2)}.cart-summary-demo label{display:grid;gap:6px;font-size:13px;font-weight:650}.cart-summary-demo input,.cart-summary-demo select,.cart-summary-demo textarea{box-sizing:border-box;width:100%;min-width:0;padding:8px;border:1px solid var(--vp-c-divider);border-radius:8px;background:var(--vp-c-bg);color:var(--vp-c-text-1);font:inherit}.cart-summary-demo select{appearance:auto}.cart-summary-demo button{padding:8px 10px;border:1px solid var(--vp-c-divider);border-radius:8px;background:var(--vp-c-bg-soft)}.cart-summary-demo button:disabled{opacity:.5;cursor:not-allowed}.cart-summary-demo :is(input,select,textarea,button):focus-visible{outline:2px solid var(--vp-c-brand-1);outline-offset:3px}.promo-row{display:flex;gap:8px}.cart-summary-demo dl>div{display:flex;justify-content:space-between;gap:12px;margin:10px 0}.cart-summary-demo dd{margin:0;white-space:nowrap}.cart-total{border-top:1px solid var(--vp-c-divider);padding-top:12px;font-weight:700}.cart-preview{padding:16px;margin-top:16px;background:var(--vp-c-bg-soft);border-radius:10px;animation:cart-preview-in .24s ease-out}.cart-preview textarea{font:12px/1.6 ui-monospace,monospace;resize:vertical}.cart-preview button,.cart-reset{margin-top:12px}.cart-empty{padding:12px;background:var(--vp-c-bg-soft)}@keyframes cart-preview-in{from{opacity:0;transform:translateY(-6px)}to{opacity:1;transform:none}}@media(max-width:700px){.cart-grid{grid-template-columns:1fr}}@media(prefers-reduced-motion:reduce){.cart-preview{animation:none}}
</style>
